  "Sol, Luna y Ascendente: el triángulo que más se nota en el día a día.": { de: "Sonne, Mond und Aszendent: das Dreieck, das man im Alltag am meisten spürt.", en: "Sun, Moon and Ascendant: the triangle you notice most day to day." },
  "Tensos": { de: "Spannungsreich", en: "Tense" },
